def tfim_9site_pbc_noisy(h, p_err, epsilon_ro):
    num_spins = 9
    qc = QuantumCircuit(num_spins)
    for i in range(num_spins):
        qc.h(np.pi / 2 * (1 - 2 * h))[i]
        qc.x(i)

    for i in range(num_spins):
        qc.cz(i, (i + 1) % num_spins)

    # Add noise and readout error
    for _ in range(int(p_err * len(qc.qubits))):
        qc.reset(np.random.randint(0, len(qc.qubits)))

    qc.measure_all()

    def compute_observables(circuit):
        result = execute(circuit, backend=BasicAer.get_backend('qasm_simulator'), shots=1000).result()
        counts = result.get_counts(circuit)
        m_x = sum([counts[f'{bin_str:0{num_spins}b}'] for bin_str in range(2**num_spins)) / (2**num_spins) * 2
        m_z = sum([counts[f'{bin_str:0{num_spins}b}'] for bin_str in range(2**num_spins)] - m_x) / (2**num_spins)
        m_z_sq = m_z ** 2
        m_z_abs_sq = abs(m_z) ** 2
        m_z_sq_4 = m_z_sq ** 2
        chi_z = 9 * (m_z_sq - m_z_abs_sq)
        U4 = 1 - m_z_sq_4 / (3 * m_z_sq ** 2)
        C_1 = (1 / 9) * sum([counts[f'1{bin_str:0{num_spins-1}b}0'] + counts[f'1{bin_str:0{num_spins-1}b}1']
                             for bin_str in range(2**(num_spins-1))])
        return {'m_x': m_x, 'chi_z': chi_z, 'U4': U4, 'C_1': C_1}

    return compute_observables(qc)

def h_c_from_chi_z(chi_z_data, index):
    chi_z_values = [chi_z_data[i]['chi_z'] for i in range(index)]
    max_index = np.argmax(chi_z_values)
    return chi_z_data[max_index]['h'] / 1.0

def zero_noise_extrapolation(observables_data, error_rates):
    r = len(observables_data) // len(error_rates)
    zne_observables = {}
    for observable_name, observable_data in observables_data.items():
        zne_observables[observable_name] = []
        for i in range(r):
            p_err = i * error_rates[0]
            for j in range(1, len(error_rates)):
                p_err += error_rates[j] * (2 ** j)
            zne_observables[observable_name].append(observable_data[p_err]['chi_z'])

    def extrapolate(coeffs, p):
        return sum([coeffs[i] * (p ** i) for i in range(len(coeffs))])

    for observable_name, observable_data in zne_observables.items():
        p_errs = [error_rates[i] for i in range(len(error_rates))]
        coeffs = np.polyfit(p_errs, observable_data, len(p_errs) - 1)
        zne_observables[observable_name].append(extrapolate(coeffs, 0))

    return zne_observables

