    def mitigate_readout(observable_data, calibration_data):
        mitigated_observable_data = {}
        for observable_name, observable_data_p in observable_data.items():
            mitigated_observable_data[observable_name] = {}
            for p_err, results in observable_data_p.items():
                corrected_results = {}
                for outcome, count in results.items():
                    corrected_outcome = calibration_data[outcome]['correction'] * outcome
                    corrected_results[corrected_outcome] = count
                mitigated_observable_data[observable_name][p_err] = corrected_results
        return mitigated_observable_data

    def calculate_calibration_matrix(samples):
        corrections = {}
        for sample in samples:
            state_vector = sample['sample_state']
            for i in range(len(state_vector)):
                if state_vector[i] == 1:
                    corrections[str(i)] = 1 - sample['probability'][str(i)]
        return corrections

    def calibrate_readout(samples, readout_error):
        corrected_samples = []
        calibration_data = calculate_calibration_matrix(samples)
        for sample in samples:
            corrected_sample = Sample()
            for outcome in sample['outcomes']:
                corrected_outcome = calibration_data[outcome] * outcome
                corrected_sample.add_outcome(corrected_outcome, sample['counts'][outcome])
            corrected_samples.append(corrected_sample)
        return corrected_samples

    data = {}
    for observable_name, observable_data in observables_data.items():
        data[observable_name] = {}
        for p_err in observables_data[observable_name]:
            data[observable_name][p_err] = mitigate_readout(observables_data[observable_name][p_err],
                                                            calibration_data)

    return data

def solve_tfim_9site_pbc_noisy():
    data = {}
    h_c_estimates = []
    critical_point_errors = []
    observable_accuracies = {}
    phase_classification_accuracies = {}
    noise_aware_performances = []

    num_spins = 9
    ham = transverse_field_ising(num_spins, J=1, h_values=quantity_to_list(1))
    bqm = BQM(ham)
    calibration_data = neal_samples(bqm, num_reads=100000)

    for p_err in [0.0, 0.005, 0.01, 0.02, 0.05]:
        observables_data = {}
        for h_val in [0.1, 1.0, 2.5]:
            observables = tfim_9site_pbc_noisy(h_val, p_err, 0.01)
            observables_data[h_val] = observables

        h_c_estimates.append(h_c_from_chi_z(observables_data, len(observables_data)))

