        observable_accuracies[p_err] = {observable_name: zne_observables[observable_name][-1] - observables_data[1.0][observable_name]
                                        for observable_name in observables_data[1.0]}
        phase_classification_accuracies[p_err] = np.mean([1 if h_c_estimates[i] > 1.0 else 0
                                                           for i in range(len(h_c_estimates))])
        noise_aware_performances.append(h_c_estimates[-1] - 1.0)

    data['estimated_critical_point'] = h_c_estimates
    data['critical_point_error'] = critical_point_errors
    data['observable_accuracy'] = observable_accuracies
    data['phase_classification_accuracy'] = phase_classification_accuracies
    data['noise_aware_performance'] = noise_aware_performances

    return data

